import { useCallback, useEffect, useRef, useState, type ReactNode } from 'react';
import { ArrowDownToLine, ArrowLeft, ArrowRight, AudioLines, BookOpen, Check, CheckCircle2, ChevronDown, ChevronRight, Circle, Clipboard, CloudOff, Copy, ExternalLink, FileText, FolderOpen, Layers3, Leaf, LoaderCircle, Menu, MessageCircle, Plus, Repeat2, Search, Settings2, Shuffle, Sparkles, Sprout, Trash2, Upload, Volume2, X } from 'lucide-react';
import Recall from './Recall';
import { AnnotatedText } from './AnnotatedText';
import { EnglishContext } from './EnglishContext';
import { MaterialDetail, ExpressionDetail } from './ReadingDetails';
import BatchImport from './BatchImport';
import QuestionChart from './QuestionChart';
import ImportPreview from './ResultPreview';
import type { Answer, Expression, ExpressionRecommendation, Job, Material, Quality, Question, Recommendation, Scope, State, Word } from './types';

type View = 'today' | 'recall' | 'speaking' | 'writing' | 'words' | 'settings';
type LibraryTab = 'topics' | 'materials' | 'expressions';
type OpenQuestion = (question: Question, prefill?: Material[]) => void;
type WordInput = { textEn: string; meaningZh: string; exampleEn: string; scope: Scope; questionId?: string };
const scopeLabel: Record<Scope, string> = { speaking: '口语', 'writing-task1': '小作文 · Task 1', 'writing-task2': '大作文 · Task 2' };
const scopeShort: Record<Scope, string> = { speaking: '口语', 'writing-task1': '小作文', 'writing-task2': '大作文' };
const dateLabel = new Intl.DateTimeFormat('zh-CN', { month: 'long', day: 'numeric', weekday: 'long', timeZone: 'Asia/Shanghai' }).format(new Date());
const navItems: { id: View; label: string; icon: typeof BookOpen }[] = [
  { id: 'today', label: '今日积累', icon: Sprout }, { id: 'recall', label: '背书', icon: Repeat2 }, { id: 'speaking', label: '口语区', icon: AudioLines }, { id: 'writing', label: '作文区', icon: FileText }, { id: 'words', label: '单词本', icon: BookOpen },
];

async function api<T>(path: string, options: RequestInit = {}): Promise<T> {
  const response = await fetch(`/api${path}`, { ...options, headers: { 'Content-Type': 'application/json', ...options.headers } });
  const payload = await response.json().catch(() => ({ error: '服务器返回了无法读取的内容。' }));
  if (!response.ok) throw Object.assign(new Error(payload.error || '请求未成功，请重试。'), { payload });
  return payload as T;
}
const post = (body: unknown): RequestInit => ({ method: 'POST', body: JSON.stringify(body) });
const errorMessage = (error: unknown) => error instanceof Error ? error.message : '操作失败，请重试。';
const wordCount = (text: string) => text.trim().split(/\s+/).filter(Boolean).length;

function Empty({ icon: Icon = FolderOpen, title, detail, action }: { icon?: typeof BookOpen; title: string; detail: string; action?: ReactNode }) {
  return <div className="empty"><span className="empty-icon"><Icon size={27} strokeWidth={1.5} /></span><h3>{title}</h3><p>{detail}</p>{action}</div>;
}
function Pill({ children, tone = '' }: { children: ReactNode; tone?: string }) { return <span className={`pill ${tone}`}>{children}</span>; }
function Modal({ title, children, close, wide = false }: { title: string; children: ReactNode; close: () => void; wide?: boolean }) {
  useEffect(() => { const handler = (event: KeyboardEvent) => { if (event.key === 'Escape') close(); }; document.addEventListener('keydown', handler); return () => document.removeEventListener('keydown', handler); }, [close]);
  return <div className="modal-overlay" onClick={close}><section className={`modal ${wide ? 'wide' : ''}`} role="dialog" aria-modal="true" aria-label={title} onClick={event => event.stopPropagation()}><header><h2>{title}</h2><button className="icon-button" aria-label="关闭" onClick={close}><X size={20} /></button></header>{children}</section></div>;
}

export default function App() {
  const [state, setState] = useState<State | null>(null);
  const [loadError, setLoadError] = useState('');
  const [view, setView] = useState<View>('today');
  const [questionId, setQuestionId] = useState<string | null>(null);
  const [questionPrefill, setQuestionPrefill] = useState<Material[]>([]);
  const [writingScope, setWritingScope] = useState<Scope>('writing-task2');
  const [toast, setToast] = useState<{ message: string; error: boolean } | null>(null);
  const [wordInput, setWordInput] = useState<WordInput | null>(null);
  const [activeMaterial, setActiveMaterial] = useState<Material | null>(null);
  const [activeExpression, setActiveExpression] = useState<Expression | null>(null);
  const [batchScope, setBatchScope] = useState<Scope | 'mixed' | null>(null);
  const [mobileMenu, setMobileMenu] = useState(false);
  const [planOpen, setPlanOpen] = useState(false);
  const [planDraft, setPlanDraft] = useState<string[]>([]);
  const [planQuery, setPlanQuery] = useState('');
  const [busy, setBusy] = useState(false);
  const notify = useCallback((message: string, error = false) => setToast({ message, error }), []);
  const reload = useCallback(async () => { const next = await api<State>('/state'); setState(next); return next; }, []);
  useEffect(() => { reload().catch(error => setLoadError(errorMessage(error))); }, [reload]);
  useEffect(() => { if (!toast) return; const timer = setTimeout(() => setToast(null), 5000); return () => clearTimeout(timer); }, [toast]);
  const navigate = (next: View) => { setView(next); setQuestionId(null); setMobileMenu(false); };
  const openQuestion: OpenQuestion = (question, prefill = []) => { setQuestionPrefill(prefill); setQuestionId(question.id); setView(question.scope === 'speaking' ? 'speaking' : 'writing'); if (question.scope !== 'speaking') setWritingScope(question.scope); window.scrollTo({ top: 0 }); };
  const currentQuestion = state?.questions.find(item => item.id === questionId);
  const currentScope: Scope = view === 'speaking' ? 'speaking' : writingScope;
  const addWord = (input: WordInput) => setWordInput(input);
  const openPlan = () => { setPlanDraft(state?.dailyPlan.questionIds || []); setPlanOpen(true); };
  const savePlan = async (ids: string[]) => { setBusy(true); try { await api('/plan', { method: 'PUT', body: JSON.stringify({ questionIds: ids }) }); await reload(); setPlanOpen(false); notify('今日计划已保存。'); } catch (error) { notify(errorMessage(error), true); } finally { setBusy(false); } };
  const addToPlan = async (id: string) => { if (!state) return; if (state.dailyPlan.questionIds.includes(id)) { notify('这道题已经在今日计划里了。'); return; } await savePlan([...state.dailyPlan.questionIds, id]); };

  if (!state) return <div className="loading-screen"><div className="brand-loading">yasy<span>.</span></div>{loadError ? <><p>{loadError}</p><button className="button primary" onClick={() => { setLoadError(''); reload().catch(error => setLoadError(errorMessage(error))); }}>重新连接本机服务</button></> : <><LoaderCircle className="spin" size={24} /><p>正在打开你的学习工作台…</p></>}</div>;

  return <EnglishContext addWord={addWord}><div className="app-shell">
    <aside className={`sidebar ${mobileMenu ? 'open' : ''}`}>
      <a href="#" className="brand" onClick={event => { event.preventDefault(); navigate('today'); }} aria-label="Yasy 首页">yasy<span>.</span><Leaf size={17} /></a>
      <div className="sidebar-caption">YOUR IELTS WORKBENCH</div>
      <nav aria-label="主导航">{navItems.map(({ id, label, icon: Icon }) => <button key={id} className={`nav-item ${view === id ? 'active' : ''}`} onClick={() => navigate(id)}><Icon size={21} strokeWidth={1.7} /><span>{label}</span>{view === id && <span className="nav-active-dot" />}</button>)}</nav>
      <div className="sidebar-bottom"><div className="target-card"><span>目标 IELTS</span><strong>{state.settings.targetBand}<small> BAND</small></strong><div className="target-note"><span /> 每天，让表达生长一点</div></div><button className={`nav-item ${view === 'settings' ? 'active' : ''}`} onClick={() => navigate('settings')}><Settings2 size={20} strokeWidth={1.7} /><span>偏好与数据</span></button><div className="local-label"><span className="status-dot" /> 本机存储 · 由你掌握</div></div>
    </aside>
    {mobileMenu && <button className="sidebar-scrim" aria-label="关闭菜单" onClick={() => setMobileMenu(false)} />}
    <div className="main-shell"><header className="topbar"><div className="topbar-left"><button className="icon-button mobile-menu" aria-label="打开菜单" onClick={() => setMobileMenu(!mobileMenu)}><Menu size={22} /></button><span className="topbar-title">{currentQuestion ? `${scopeShort[currentQuestion.scope]}练习` : { today: '今日积累', recall: '背书', speaking: '口语区', writing: '作文区', words: '单词本', settings: '偏好与数据' }[view]}</span><span className="topbar-separator" /><span className="topbar-subtitle">真实素材，自己的表达</span></div><div className="topbar-right"><span className="local-status"><span className="status-dot" /> LOCAL FIRST</span><span className="avatar">Y</span></div></header>
    <main className={`main-content ${currentQuestion ? 'workspace-content' : ''}`}>
      {currentQuestion ? <Workspace key={currentQuestion.id} question={currentQuestion} prefill={questionPrefill} state={state} reload={reload} notify={notify} goBack={() => setQuestionId(null)} openQuestion={openQuestion} addWord={addWord} addToPlan={addToPlan} onMaterial={setActiveMaterial} onExpression={setActiveExpression} /> : view === 'today' ? <Today state={state} openQuestion={openQuestion} navigate={navigate} openPlan={openPlan} onMaterial={setActiveMaterial} onExpression={setActiveExpression} /> : view === 'recall' ? <Recall state={state} notify={notify} onMaterial={setActiveMaterial} onExpression={setActiveExpression} /> : (view === 'speaking' || view === 'writing') ? <Library key={currentScope} scope={currentScope} state={state} writingScope={writingScope} setWritingScope={setWritingScope} openQuestion={openQuestion} addToPlan={addToPlan} addWord={addWord} onExpression={setActiveExpression} openBatch={() => setBatchScope(currentScope)} /> : view === 'words' ? <Words state={state} reload={reload} notify={notify} addWord={addWord} /> : <Settings state={state} setState={setState} reload={reload} notify={notify} openBatch={() => setBatchScope('mixed')} />}
    </main><footer className="page-footer"><span>yasy · 每一份素材都属于你</span><span>Mac 工作台 <span className="footer-dot">·</span> iPhone 阅读适配</span></footer></div>
    {toast && <div className={`toast ${toast.error ? 'error' : ''}`} role="status">{toast.error ? <Circle size={18} /> : <CheckCircle2 size={18} />}<span>{toast.message}</span><button aria-label="关闭提示" onClick={() => setToast(null)}><X size={16} /></button></div>}
    {activeMaterial && <MaterialDetail material={activeMaterial} state={state} close={() => setActiveMaterial(null)} openQuestion={openQuestion} onExpression={setActiveExpression} />}
    {activeExpression && <ExpressionDetail expression={activeExpression} close={() => setActiveExpression(null)} addWord={addWord} />}
    {batchScope && <BatchImport initialScope={batchScope} close={() => setBatchScope(null)} notify={notify} onSaved={setState} />}
    {wordInput && <WordModal input={wordInput} close={() => setWordInput(null)} saved={async () => { await reload(); setWordInput(null); notify('已收进单词本。'); }} notify={notify} />}
    {planOpen && <Modal title="安排今日积累" close={() => setPlanOpen(false)} wide><p className="modal-description">为口语和作文各挑几道题。完成答案后，会自动标记已完成。</p><div className="search-box"><Search size={17} /><input aria-label="搜索计划题目" placeholder="搜索话题或题目…" value={planQuery} onChange={event => setPlanQuery(event.target.value)} /></div><div className="plan-targets"><span>每日目标：口语 {state.settings.dailySpeaking} 道 / 作文 {state.settings.dailyWriting} 道</span><button className="text-button" onClick={() => { const available = state.questions.filter(question => !state.answers.some(answer => answer.questionId === question.id)); setPlanDraft([...available.filter(question => question.scope === 'speaking').slice(0, state.settings.dailySpeaking), ...available.filter(question => question.scope !== 'speaking').slice(0, state.settings.dailyWriting)].map(question => question.id)); }}><Sparkles size={14} />按目标推荐</button></div><div className="plan-picker">{state.questions.filter(question => `${question.titleZh} ${question.promptEn}`.toLowerCase().includes(planQuery.toLowerCase())).map(question => <label className="plan-pick-row" key={question.id}><input type="checkbox" checked={planDraft.includes(question.id)} onChange={event => setPlanDraft(event.target.checked ? [...planDraft, question.id] : planDraft.filter(id => id !== question.id))} /><span><small>{scopeLabel[question.scope]}{question.part ? ` / ${question.part}` : ''}</small><strong>{question.titleZh}</strong></span>{state.answers.some(answer => answer.questionId === question.id) && <Pill tone="green">已有答案</Pill>}</label>)}</div><div className="modal-actions"><span className="muted">已选 {planDraft.length} 道</span><button className="button primary" disabled={busy} onClick={() => savePlan(planDraft)}>{busy ? <LoaderCircle size={16} className="spin" /> : <Check size={16} />} 保存今日计划</button></div></Modal>}
  </div></EnglishContext>;
}

function Today({ state, openQuestion, navigate, openPlan, onMaterial, onExpression }: { state: State; openQuestion: OpenQuestion; navigate: (view: View) => void; openPlan: () => void; onMaterial: (material: Material) => void; onExpression: (expression: Expression) => void }) {
  const planned = state.dailyPlan.questionIds.map(id => state.questions.find(question => question.id === id)).filter((item): item is Question => !!item);
  const done = planned.filter(question => state.answers.some(answer => answer.questionId === question.id)).length;
  const recent = [...state.answers].sort((a, b) => b.updatedAt.localeCompare(a.updatedAt)).slice(0, 3);
  return <><div className="page-heading"><div><div className="eyebrow">A LITTLE BETTER, EVERY DAY</div><h1>今日积累<span className="heading-dot">.</span></h1><p>{dateLabel} <span className="inline-dot">·</span> 从一个真实的故事开始。</p></div><button className="button secondary" onClick={openPlan}><Plus size={17} />安排今日任务</button></div>
    <section className="welcome-card"><div className="welcome-copy"><Pill tone="paper"><Leaf size={13} /> YOUR OWN WORDS</Pill><h2>把你的故事，<br />变成<span>自然的英语。</span></h2><p>先用中文讲清楚，再积累英文表达。<br />一个好素材，可以走进不止一道题。</p><button className="button dark" onClick={openPlan}>开始今天的积累 <ArrowRight size={17} /></button></div><div className="welcome-art" aria-hidden="true"><span className="art-orbit orbit-one" /><span className="art-orbit orbit-two" /><span className="art-dot dot-one" /><span className="art-dot dot-two" /><div className="art-material"><div className="art-label"><Layers3 size={16} /> 真实素材</div><div className="art-line long" /><div className="art-line" /><div className="art-tags"><span>经历</span><span>感受</span></div></div><div className="art-expression"><span className="art-star">✳</span><small>好词 · 好句</small><strong>Make it<br /><em>your own.</em></strong><div className="art-line long" /></div><span className="art-connector">↗</span></div></section>
    <div className="stats-grid"><Stat value={state.answers.length} label="已整理答案" icon={MessageCircle} /><Stat value={state.materials.length} label="真实素材元" icon={Layers3} /><Stat value={state.expressions.length} label="收藏好词句" icon={Sparkles} /><Stat value={state.words.length} label="单词本积累" icon={BookOpen} /></div>
    <div className="today-grid"><section className="card daily-card"><div className="section-heading"><div><h2>今天的练习</h2><p>一步一步，建立自己的答案库</p></div><span className="small-count">{done} / {planned.length} 完成</span></div><div className="progress-track"><span style={{ width: planned.length ? `${done / planned.length * 100}%` : '0%' }} /></div>{planned.length ? <div className="daily-task-list">{(['speaking', 'writing-task2', 'writing-task1'] as Scope[]).map(scope => { const items = planned.filter(question => question.scope === scope); return items.length ? <div key={scope}><div className="task-group-label">{scope === 'speaking' ? <AudioLines size={16} /> : <FileText size={16} />} {scopeLabel[scope]} <span>{items.length} 道</span></div>{items.map(question => <TaskRow key={question.id} question={question} completed={state.answers.some(answer => answer.questionId === question.id)} openQuestion={openQuestion} />)}</div> : null; })}</div> : <Empty icon={Sprout} title="今天，从一道题开始" detail="题库已经准备好。挑选今天想练习的口语和作文，写下属于你的中文素材。" action={<button className="button primary" onClick={openPlan}><Plus size={16} />挑选今日题目</button>} />}</section><aside className="today-right"><section className="practice-note"><div className="note-top"><Sparkles size={19} /><span>YASY METHOD</span></div><h3>两条线，一起生长。</h3><p>素材线，记录你真实的经历和观点。<br />表达线，积累自然、准确的好词句。</p><div className="method-row"><span>中文素材</span><ChevronRight size={14} /><span>组织答案</span></div><div className="method-row"><span>素材复用</span><span className="method-plus">＋</span><span>表达积累</span></div><small>口语与作文独立积累，单词本统一收藏。</small></section><section className="quick-access"><h3>继续探索</h3><button onClick={() => navigate('speaking')}><span className="quick-icon"><AudioLines size={20} /></span><span><strong>口语全话题</strong><small>Part 1 · Part 2 · Part 3</small></span><ArrowRight size={17} /></button><button onClick={() => navigate('writing')}><span className="quick-icon peach"><FileText size={20} /></span><span><strong>作文题库</strong><small>Academic Task 1 / Task 2</small></span><ArrowRight size={17} /></button></section></aside></div>
    <section className="recent-section"><div className="section-heading"><div><h2>最近的积累</h2><p>每一份完成的答案，都是下次表达的起点</p></div></div>{recent.length ? <div className="recent-grid">{recent.map(answer => { const question = state.questions.find(item => item.id === answer.questionId); return question && <button className="recent-card" key={answer.id} onClick={() => openQuestion(question)}><Pill>{scopeShort[question.scope]}</Pill><h3>{question.titleZh}</h3><p><AnnotatedText text={answer.textEn} answer={answer} materials={state.materials.filter(item => answer.materialIds.includes(item.id))} expressions={state.expressions.filter(item => answer.expressionIds.includes(item.id))} scope={question.scope} questionId={question.id} onMaterial={onMaterial} onExpression={onExpression} /></p><span>查看答案 <ArrowRight size={15} /></span></button>; })}</div> : <div className="recent-empty"><BookOpen size={18} /><span>完成第一道题后，答案会出现在这里。</span></div>}</section>
  </>;
}
function Stat({ value, label, icon: Icon }: { value: number; label: string; icon: typeof BookOpen }) { return <div className="stat-card"><div><strong>{value}<small>份</small></strong><span>{label}</span></div><Icon size={24} strokeWidth={1.5} /></div>; }
function TaskRow({ question, completed, openQuestion }: { question: Question; completed: boolean; openQuestion: OpenQuestion }) { return <button className="task-row" onClick={() => openQuestion(question)}>{completed ? <CheckCircle2 className="completed-icon" size={21} /> : <Circle className="uncompleted-icon" size={21} />}<span className="task-title"><strong>{question.titleZh}</strong><small>{question.part || question.taskType || 'Writing'} <span>·</span> {question.promptEn.length > 95 ? `${question.promptEn.slice(0, 95)}…` : question.promptEn}</small></span><span className={completed ? 'task-state complete' : 'task-state'}>{completed ? '查看答案' : '开始积累'}<ArrowRight size={15} /></span></button>; }

function Library({ scope, state, writingScope, setWritingScope, openQuestion, addToPlan, addWord, onExpression, openBatch }: { scope: Scope; state: State; writingScope: Scope; setWritingScope: (scope: Scope) => void; openQuestion: OpenQuestion; addToPlan: (id: string) => void; addWord: (input: WordInput) => void; onExpression: (expression: Expression) => void; openBatch: () => void }) {
  const [tab, setTab] = useState<LibraryTab>('topics');
  const [query, setQuery] = useState('');
  const [part, setPart] = useState('all');
  const [topicId, setTopicId] = useState<string | null>(null);
  const [detailMaterial, setDetailMaterial] = useState<Material | null>(null);
  const [materialLanguage, setMaterialLanguage] = useState<'en' | 'zh'>('en');
  const questions = state.questions.filter(question => question.scope === scope);
  const matchQuestion = (question: Question) => { const topic = state.topics.find(item => item.id === question.topicId); return (part === 'all' || question.part === part) && `${topic?.titleZh || ''} ${topic?.titleEn || ''} ${question.titleZh} ${question.promptEn} ${question.promptZh} ${question.tags.join(' ')}`.toLowerCase().includes(query.toLowerCase()); };
  const topics = state.topics.filter(topic => topic.scope === scope && (questions.some(question => question.topicId === topic.id && matchQuestion(question)) || (!query && part === 'all')));
  const activeTopic = state.topics.find(topic => topic.id === topicId);
  const materials = state.materials.filter(material => material.scope === scope && `${material.title} ${material.summaryZh} ${material.tags.join(' ')}`.toLowerCase().includes(query.toLowerCase()));
  const expressions = state.expressions.filter(expression => expression.scope === scope && `${expression.textEn} ${expression.meaningZh} ${expression.category}`.toLowerCase().includes(query.toLowerCase()));
  const counts = { topics: questions.length, materials: state.materials.filter(item => item.scope === scope).length, expressions: state.expressions.filter(item => item.scope === scope).length };
  return <><div className="page-heading"><div><div className="eyebrow">{scope === 'speaking' ? 'SPEAK WITH YOUR OWN STORIES' : 'WRITE WITH A CLEAR PURPOSE'}</div><h1>{scope === 'speaking' ? '口语区' : '作文区'}<span className="heading-dot">.</span></h1><p>{scope === 'speaking' ? '真实经历 × 自然表达，为每一道题准备自己的答案。' : '从观点到论证，从图表到概述。用适合写作的语言，建立完整答案。'}</p></div><button className="button secondary" onClick={openBatch}><Upload size={16} />批量导入题库</button></div>
    {scope !== 'speaking' && <div className="writing-switch"><button className={writingScope === 'writing-task2' ? 'selected' : ''} onClick={() => setWritingScope('writing-task2')}><FileText size={18} /><span>大作文<small>TASK 2 · 观点与论证</small></span></button><button className={writingScope === 'writing-task1' ? 'selected' : ''} onClick={() => setWritingScope('writing-task1')}><Layers3 size={18} /><span>小作文<small>TASK 1 · Academic 图表</small></span></button></div>}
    <div className="library-toolbar"><div className="tabs">{([{ id: 'topics', label: '全话题题库', icon: FolderOpen }, { id: 'materials', label: '素材库', icon: Layers3 }, { id: 'expressions', label: '语料库', icon: Sparkles }] as const).filter(item => !(scope === 'writing-task1' && item.id === 'materials')).map(({ id, label, icon: Icon }) => <button className={tab === id ? 'active' : ''} key={id} onClick={() => { setTab(id); setQuery(''); setTopicId(null); }}><Icon size={17} />{label}<span>{counts[id]}</span></button>)}</div><div className="search-box"><Search size={17} /><input value={query} onChange={event => setQuery(event.target.value)} aria-label="搜索当前题库或积累" placeholder={tab === 'topics' ? '搜索话题、题目…' : tab === 'materials' ? '搜索你的素材…' : '搜索表达、中文含义…'} />{query && <button aria-label="清空搜索" onClick={() => setQuery('')}><X size={15} /></button>}</div></div>
    {tab === 'topics' && <><div className="library-info"><span>{activeTopic ? <button className="text-button" onClick={() => setTopicId(null)}><ArrowLeft size={15} />全部话题</button> : <>{topics.length} 个主题 <span className="inline-dot">·</span> {questions.length} 道练习题</>}</span>{scope === 'speaking' && <div className="segmented small">{['all', 'Part 1', 'Part 2', 'Part 3'].map(item => <button key={item} className={part === item ? 'selected' : ''} onClick={() => setPart(item)}>{item === 'all' ? '全部' : item}</button>)}</div>}</div>{activeTopic ? <section className="card topic-detail"><div className="topic-detail-heading"><div><span className="eyebrow">{activeTopic.titleEn}</span><h2>{activeTopic.titleZh}</h2><p>{activeTopic.description}</p></div><span className="topic-glyph"><MessageCircle size={27} strokeWidth={1.4} /></span></div>{questions.filter(question => question.topicId === activeTopic.id && matchQuestion(question)).map(question => <QuestionRow key={question.id} question={question} state={state} openQuestion={openQuestion} addToPlan={addToPlan} />)}</section> : topics.length ? <div className="topic-grid">{topics.map((topic, index) => { const items = questions.filter(question => question.topicId === topic.id); const completed = items.filter(question => state.answers.some(answer => answer.questionId === question.id)).length; return <button className="topic-card" key={topic.id} onClick={() => setTopicId(topic.id)}><div className="topic-card-top"><span className={`topic-icon color-${index % 4}`}>{scope === 'speaking' ? <MessageCircle size={22} strokeWidth={1.5} /> : <FileText size={22} strokeWidth={1.5} />}</span><span className="topic-card-arrow"><ArrowRight size={18} /></span></div><h3>{topic.titleZh}</h3><span className="topic-en">{topic.titleEn}</span><p>{topic.description}</p><div className="topic-tags">{[...new Set(items.map(question => question.part || question.taskType).filter(Boolean))].slice(0, 3).map(tag => <span key={tag}>{tag}</span>)}</div><div className="topic-card-footer"><span>{items.length} 道题</span><span>{completed ? `${completed} 道已积累` : '等待你的第一个故事'}</span></div></button>; })}</div> : <Empty title="没有匹配的题目" detail="试试其他关键词，或切换 Part 筛选。" />}
    <div className="source-note"><BookOpen size={16} /><p>题目保留来源：官方样题、考生回忆与基于样题的改编练习分别标记。回忆题未经官方确认，题库不代表完整在考题单。</p></div></>}
    {tab === 'materials' && <><div className="library-info"><span>每个素材元保存核心经历或论点，与具体题目的问法解耦。</span><div className="segmented small"><button className={materialLanguage === 'en' ? 'selected' : ''} onClick={() => setMaterialLanguage('en')}>English</button><button className={materialLanguage === 'zh' ? 'selected' : ''} onClick={() => setMaterialLanguage('zh')}>中文</button></div></div>{materials.length ? <div className="collection-grid">{materials.map(material => <button className="material-card card" key={material.id} onClick={() => setDetailMaterial(material)}><div className="collection-card-top"><Layers3 size={19} /><Pill>{material.tags[0] || '真实素材'}</Pill></div><h3>{materialLanguage === 'en' ? material.summaryEn || 'Original material' : material.title}</h3><p data-word-scope={material.scope}>{materialLanguage === 'en' ? material.detailEn || 'English version pending. Reprocess the original answer to add it.' : material.summaryZh}</p><div className="card-bottom"><span>{state.links.filter(link => link.kind === 'material-question' && link.fromId === material.id).length} 道关联题目</span><ArrowRight size={16} /></div></button>)}</div> : <Empty icon={Layers3} title={query ? '没有匹配的素材' : '你的真实素材，从这里生长'} detail={query ? '试试其他关键词。' : '完成一次口语或大作文处理后，拆解出的素材元会自动存入本域素材库。'} />}</>}
    {tab === 'expressions' && <><div className="library-info"><span>积累表达情感、态度、逻辑和描述的好词句。</span><Pill tone="green">{scopeShort[scope]}专属语料库</Pill></div>{expressions.length ? <div className="collection-grid">{expressions.map(expression => <ExpressionCard key={expression.id} expression={expression} addWord={addWord} onExpression={onExpression} />)}</div> : <Empty icon={Sparkles} title={query ? '没有匹配的表达' : '积累第一句，表达就有了起点'} detail={query ? '可以搜索英文表达或中文意思。' : 'AI 整理答案时提取的好词句会保存在这里，并与本域素材建立关联。'} />}</>}
    {detailMaterial && <MaterialDetail material={detailMaterial} state={state} close={() => setDetailMaterial(null)} openQuestion={openQuestion} onExpression={onExpression} />}
  </>;
}
function QuestionRow({ question, state, openQuestion, addToPlan }: { question: Question; state: State; openQuestion: OpenQuestion; addToPlan: (id: string) => void }) {
  const source = state.sources.find(item => item.id === question.sourceId);
  return <div className="question-row"><div className="question-row-body" onClick={() => openQuestion(question)}><div className="question-pills"><Pill>{question.part || question.taskType || scopeShort[question.scope]}</Pill><Pill tone={question.sourceType === 'official' ? 'green' : question.sourceType === 'reported' ? 'orange' : ''}>{question.sourceType === 'official' ? '官方样题' : question.sourceType === 'reported' ? '考生回忆' : '改编练习'}</Pill>{state.answers.some(answer => answer.questionId === question.id) && <Pill tone="green"><Check size={12} /> 已积累</Pill>}</div><button className="question-title" onClick={() => openQuestion(question)}>{question.titleZh}</button><p>{question.promptEn}</p>{source && <a className="source-link" href={source.url} target="_blank" rel="noreferrer" onClick={event => event.stopPropagation()}>{source.title}<ExternalLink size={11} /></a>}</div><div className="question-row-actions"><button className="icon-button add-plan" aria-label={`将${question.titleZh}加入今日任务`} title="加入今日任务" onClick={() => addToPlan(question.id)}>{state.dailyPlan.questionIds.includes(question.id) ? <Check size={18} /> : <Plus size={18} />}</button><button className="button primary small-button" onClick={() => openQuestion(question)}>开始练习<ArrowRight size={15} /></button></div></div>;
}
function ExpressionCard({ expression, addWord, onExpression }: { expression: Expression; addWord: (input: WordInput) => void; onExpression: (expression: Expression) => void }) { return <article className="expression-card card" data-word-scope={expression.scope}><div className="collection-card-top"><Pill tone="green">{expression.categoryEn || 'Useful expression'}</Pill><button className="icon-button" aria-label={`收藏 ${expression.textEn}`} title="Add to vocabulary" onClick={() => addWord({ textEn: expression.textEn, meaningZh: expression.meaningZh, exampleEn: expression.exampleEn, scope: expression.scope })}><Plus size={17} /></button></div><button className="expression-card-content" onClick={() => onExpression(expression)}><h3 className="expression-underline">{expression.textEn}</h3><blockquote>{expression.exampleEn}</blockquote>{expression.usageNoteEn && <small className="usage-note">{expression.usageNoteEn}</small>}</button></article>; }

function Workspace({ question, prefill, state, reload, notify, goBack, openQuestion, addWord, addToPlan, onMaterial, onExpression }: { question: Question; prefill: Material[]; state: State; reload: () => Promise<State>; notify: (message: string, error?: boolean) => void; goBack: () => void; openQuestion: OpenQuestion; addWord: (input: WordInput) => void; addToPlan: (id: string) => void; onMaterial: (material: Material) => void; onExpression: (expression: Expression) => void }) {
  const draft = state.drafts.find(item => item.questionId === question.id);
  const [textZh, setTextZh] = useState([draft?.textZh || '', ...prefill.filter(material => !draft?.materialIds.includes(material.id)).map(material => `【${material.title}】\n${material.detailZh}`)].filter(Boolean).join('\n\n'));
  const [materialIds, setMaterialIds] = useState<string[]>([...new Set([...(draft?.materialIds || []), ...prefill.map(material => material.id)])]);
  const [recommendations, setRecommendations] = useState<Recommendation[]>([]);
  const [expressionRecommendations, setExpressionRecommendations] = useState<ExpressionRecommendation[]>([]);
  const [quality, setQuality] = useState<Quality | null>(null);
  const [job, setJob] = useState<Job | null>([...state.jobs].filter(item => item.questionId === question.id).sort((a, b) => b.createdAt.localeCompare(a.createdAt))[0] || null);
  const [importText, setImportText] = useState('');
  const [preview, setPreview] = useState<Record<string, unknown> | null>(null);
  const [step, setStep] = useState<'write' | 'bridge' | 'answer'>(state.answers.some(item => item.questionId === question.id) ? 'answer' : 'write');
  const [busy, setBusy] = useState('');
  const [saveStatus, setSaveStatus] = useState('已保存到本机');
  const [showPrompt, setShowPrompt] = useState(false);
  const editorRef = useRef<HTMLTextAreaElement>(null);
  const initialSave = useRef(prefill.length === 0);
  const latestDraft = useRef({ textZh, materialIds, dirty: prefill.length > 0 });
  latestDraft.current.textZh = textZh;
  latestDraft.current.materialIds = materialIds;
  const answer = state.answers.find(item => item.questionId === question.id);
  const source = state.sources.find(item => item.id === question.sourceId);
  const answerMaterials = state.materials.filter(item => answer?.materialIds.includes(item.id));
  const answerExpressions = state.expressions.filter(item => answer?.expressionIds.includes(item.id));
  const questionList = state.questions.filter(item => item.scope === question.scope);
  const nextQuestion = questionList[questionList.findIndex(item => item.id === question.id) + 1];
  useEffect(() => { api<{ materials: Recommendation[]; expressions: ExpressionRecommendation[] }>(`/questions/${question.id}/recommendations`).then(result => { setRecommendations(result.materials); setExpressionRecommendations(result.expressions); }).catch(error => notify(errorMessage(error), true)); }, [question.id, state.materials.length, state.expressions.length, notify]);
  useEffect(() => {
    if (initialSave.current) { initialSave.current = false; return; }
    latestDraft.current.dirty = true;
    setSaveStatus('保存中…');
    const timer = setTimeout(() => { api(`/drafts/${question.id}`, { method: 'PUT', body: JSON.stringify({ textZh, materialIds }) }).then(async () => { if (latestDraft.current.textZh === textZh && JSON.stringify(latestDraft.current.materialIds) === JSON.stringify(materialIds)) { latestDraft.current.dirty = false; setSaveStatus('已保存到本机'); } await reload(); }).catch(error => { setSaveStatus('保存失败'); notify(errorMessage(error), true); }); }, 600);
    return () => clearTimeout(timer);
  }, [textZh, materialIds, question.id, notify, reload]);
  useEffect(() => { const flush = () => { const current = latestDraft.current; if (current.dirty) { const snapshot = { textZh: current.textZh, materialIds: [...current.materialIds] }; api(`/drafts/${question.id}`, { method: 'PUT', keepalive: true, body: JSON.stringify(snapshot) }).then(() => { if (latestDraft.current.textZh === snapshot.textZh && JSON.stringify(latestDraft.current.materialIds) === JSON.stringify(snapshot.materialIds)) latestDraft.current.dirty = false; return reload(); }).catch(error => notify(errorMessage(error), true)); } }; const onVisibility = () => { if (document.visibilityState === 'hidden') flush(); }; window.addEventListener('pagehide', flush); document.addEventListener('visibilitychange', onVisibility); return () => { window.removeEventListener('pagehide', flush); document.removeEventListener('visibilitychange', onVisibility); flush(); }; }, [question.id, reload, notify]);
  const selectMaterial = (material: Material) => { const block = `【${material.title}】\n${material.detailZh}`; if (materialIds.includes(material.id)) { setMaterialIds(materialIds.filter(id => id !== material.id)); setTextZh(textZh.replace(block, '').trim()); } else { setMaterialIds([...materialIds, material.id]); setTextZh([textZh.trim(), block].filter(Boolean).join('\n\n')); } setQuality(null); };
  const checkQuality = async () => { setBusy('quality'); try { const result = await api<Quality>('/quality', post({ questionId: question.id, textZh })); setQuality(result); if (result.passed) notify('素材初检通过，可以生成专属提示词。'); } catch (error) { notify(errorMessage(error), true); } finally { setBusy(''); } };
  const createJob = async () => { setBusy('job'); try { await api(`/drafts/${question.id}`, { method: 'PUT', body: JSON.stringify({ textZh, materialIds }) }); const result = await api<{ job: Job; prompt: string; quality: Quality }>('/jobs', post({ questionId: question.id, textZh, materialIds })); setQuality(result.quality); setJob(result.job); setStep('bridge'); await reload(); notify('专属提示词已生成，已保存本次处理任务。'); } catch (error) { const payload = (error as { payload?: { quality?: Quality } }).payload; if (payload?.quality) setQuality(payload.quality); notify(errorMessage(error), true); } finally { setBusy(''); } };
  const copyPrompt = async (open = false) => { if (!job) return; try { await navigator.clipboard.writeText(job.prompt); if (open) window.open('https://chatgpt.com', '_blank', 'noopener,noreferrer'); notify(open ? '提示词已复制，在 ChatGPT 新对话中粘贴即可。' : '提示词已复制。'); } catch { setShowPrompt(true); notify('浏览器未允许复制，请从展开的提示词中手动复制。', true); } };
  const parsePreview = () => { try { const cleaned = importText.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, ''); const parsed = JSON.parse(cleaned); if (parsed?.answer && (typeof parsed.answer !== 'object' || typeof parsed.answer.textEn !== 'string')) throw new Error('answer.textEn 必须是英文答案文本。'); if (parsed?.quality?.suggestions !== undefined && !Array.isArray(parsed.quality.suggestions)) throw new Error('quality.suggestions 必须是数组。'); if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) throw new Error('请粘贴完整 JSON 对象。'); if (parsed.questionId && parsed.questionId !== question.id) throw new Error('这份结果属于其他题目，请核对 questionId。'); if (parsed.requestId && parsed.requestId !== job?.id) throw new Error('这份结果属于其他处理任务，请使用当前提示词生成的结果。'); if (parsed.scope && parsed.scope !== question.scope) throw new Error('这份结果的口语 / 写作领域与当前题目不一致。'); setPreview(parsed); } catch (error) { notify(`无法预览：${errorMessage(error)}`, true); } };
  const importResult = async () => { if (!job || !preview) return; setBusy('import'); try { await api(`/jobs/${job.id}/result`, post({ result: preview })); await reload(); setPreview(null); setImportText(''); setStep('answer'); notify('答案、素材与表达已整理入库。'); } catch (error) { const payload = (error as { payload?: { quality?: Quality } }).payload; if (payload?.quality) { setQuality(payload.quality); setStep('write'); setPreview(null); } notify(errorMessage(error), true); } finally { setBusy(''); } };
  const selectedAnswerWord = () => { const selection = window.getSelection()?.toString().trim(); if (!selection) { notify('请先选中答案里的英文单词或短语。'); return; } addWord({ textEn: selection, meaningZh: '', exampleEn: '', scope: question.scope, questionId: question.id }); };
  const outbound = answerMaterials.flatMap(material => state.links.filter(link => link.kind === 'material-question' && link.fromId === material.id && link.toId !== question.id).map(link => ({ ...link, material }))).sort((a, b) => b.score - a.score).filter((item, index, array) => array.findIndex(other => other.toId === item.toId) === index).slice(0, 3);

  return <><div className="workspace-top"><button className="text-button" onClick={goBack}><ArrowLeft size={17} />返回题库</button><span className="save-status"><Check size={13} /> {saveStatus}</span></div><div className="workspace-heading"><div><div className="question-pills"><Pill tone="green">{scopeLabel[question.scope]}</Pill>{question.part && <Pill>{question.part}</Pill>}<Pill tone={question.sourceType === 'reported' ? 'orange' : ''}>{question.sourceType === 'official' ? '官方样题' : question.sourceType === 'reported' ? '考生回忆' : '改编练习'}</Pill></div><h1>{question.titleZh}</h1></div><button className="button secondary small-button" onClick={() => addToPlan(question.id)}>{state.dailyPlan.questionIds.includes(question.id) ? <Check size={16} /> : <Plus size={16} />}今日任务</button></div>
    <section className="question-prompt card"><div className="prompt-eyebrow">YOUR QUESTION</div><p className="question-english" data-word-scope={question.scope} data-word-question={question.id}>{question.promptEn}</p>{question.cuePoints?.length ? <ul className="cue-points">{question.cuePoints.map(point => <li key={point}>{point}</li>)}</ul> : null}<p className="question-chinese">{question.promptZh}</p>{question.visual && <QuestionVisual question={question} />}{source && <div className="prompt-source"><a href={source.url} target="_blank" rel="noreferrer">来源：{source.title}<ExternalLink size={12} /></a>{question.basis && <span>{question.basis}</span>}{question.reportedAt && <span>回忆时间：{question.reportedAt}</span>}</div>}</section>
    <div className="workspace-steps">{([{ id: 'write', label: '写下中文素材', number: '01' }, { id: 'bridge', label: 'AI 整理与提取', number: '02' }, { id: 'answer', label: '答案与积累', number: '03' }] as const).map(({ id, label, number }) => <button key={id} className={step === id ? 'active' : ''} disabled={(id === 'bridge' && !job) || (id === 'answer' && !answer)} onClick={() => setStep(id)}><span>{id === 'answer' && answer ? <Check size={14} /> : number}</span>{label}<ChevronRight size={16} /></button>)}</div>
    {step === 'write' && <div className="workspace-grid"><section className="card editor-card"><div className="section-heading"><div><h2>{question.scope === 'writing-task1' ? '先读图，再组织信息' : '先用中文，写下你的素材'}</h2><p>{question.scope === 'speaking' ? '具体的经历、细节和感受，比空泛的套话更有用。' : question.scope === 'writing-task1' ? '写出总体趋势、关键对比与准确数据，不虚构个人经历。' : '明确立场，写出理由、例子与论证。真实素材也可以是你的观察。'}</p></div><Pill>{textZh.length} 字</Pill></div><textarea ref={editorRef} className="chinese-editor" value={textZh} onChange={event => { setTextZh(event.target.value); setQuality(null); }} aria-label="中文素材编辑器" placeholder={question.scope === 'speaking' ? '不需要先想英文。\n\n发生了什么？和谁、在哪里、什么时候？\n有哪个具体细节让你印象深刻？\n你的感受是什么，为什么？\n\n也可以从右侧挑选相关素材，修改成适合这道题的故事。' : question.scope === 'writing-task1' ? '总体趋势 / 主要特征：\n\n关键数据和比较：\n\n分组方式：\n\n请以题目给出的图表数据为依据。' : '我的立场：\n\n理由一 + 解释 + 具体例子：\n\n理由二 + 解释 + 具体例子：\n\n可讨论的另一面：'} /><div className="editor-bottom"><span><CloudOff size={14} /> 中文素材自动保存</span><span>{materialIds.length ? `已选 ${materialIds.length} 个素材元` : '先真实，再流畅'}</span></div>
      {quality && <QualityPanel quality={quality} />}
      <div className="editor-actions"><button className="button secondary" disabled={!!busy || !textZh.trim()} onClick={checkQuality}>{busy === 'quality' ? <LoaderCircle className="spin" size={16} /> : <CheckCircle2 size={16} />}检查素材</button><button className="button primary" disabled={!!busy || !textZh.trim()} onClick={createJob}>{busy === 'job' ? <LoaderCircle className="spin" size={16} /> : <Sparkles size={16} />}生成专属提示词<ArrowRight size={15} /></button></div></section><aside className="workspace-aside"><section className="card recommendation-card"><div className="section-heading"><div><h3>{question.scope === 'writing-task1' ? '相关写作表达' : '可能用得上的素材'}</h3><p>{question.scope === 'writing-task1' ? '小作文独立积累图表语料' : '本域素材检索 · 相关度 Top 3'}</p></div><Layers3 size={19} /></div>{question.scope === 'writing-task1' ? (expressionRecommendations.length ? expressionRecommendations.map(item => <div className="compact-expression" key={item.expression.id}><strong className="expression-underline" data-word-scope={question.scope} onClick={() => onExpression(item.expression)}>{item.expression.textEn}</strong><p data-word-scope={question.scope}>{item.expression.exampleEn}</p></div>) : <div className="recommendation-empty"><Sparkles size={27} strokeWidth={1.3} /><p>还没有可推荐的表达</p><small>完成第一篇小作文后，图表描述语料会在这里积累。</small></div>) : recommendations.length ? recommendations.slice(0, 3).map((item, index) => <button className={`recommendation-item ${materialIds.includes(item.material.id) ? 'selected' : ''}`} key={item.material.id} onClick={() => selectMaterial(item.material)}><div><span className="recommendation-rank">0{index + 1}</span><span className="recommendation-choice">{materialIds.includes(item.material.id) ? <Check size={13} /> : <Plus size={13} />}</span></div><h4>{item.material.title}</h4><p>{item.material.summaryZh}</p><small>{item.reason}</small><span className="recommendation-action">{materialIds.includes(item.material.id) ? '已填入草稿 · 可编辑' : '选择并填入中文素材'}</span></button>) : <div className="recommendation-empty"><Layers3 size={27} strokeWidth={1.3} /><p>这是一个新的起点</p><small>还没有相关素材。写下第一个真实故事，之后系统会为其他题目推荐它。</small></div>}</section><div className="workspace-tip"><Leaf size={19} /><h4>素材可复用，答案要贴题。</h4><p>{question.scope === 'writing-task1' ? '图表写作关注客观描述。每次处理都使用专属 Task 1 提示词。' : '可以选择多个素材元。预填写后，请补充本题需要的细节，让它成为你的回答。'}</p></div></aside></div>}
    {step === 'bridge' && job && <>{job.textZh !== textZh && <div className="quality-panel stale-job"><div><Circle size={16} /><strong>中文素材已更新，当前提示词需要重新生成</strong></div><p>返回中文素材步骤生成新提示词，确保导入的答案与你最新的素材一致。</p><button className="text-button" onClick={() => setStep('write')}><ArrowLeft size={14} />返回中文素材</button></div>}<div className="bridge-grid"><section className="card bridge-card"><div className="bridge-number">01</div><h2>把提示词交给 ChatGPT</h2><p>已包含本题、你的中文素材、{scopeShort[question.scope]}专属要求与 JSON 输出格式。</p><div className="bridge-info"><MessageCircle size={19} /><span>ChatGPT 网页桥接<small>复制 → 网页处理 → 粘贴结果</small></span><Pill tone="green">手动确认</Pill></div><button className="button primary full-width" onClick={() => copyPrompt(true)}><Copy size={17} />复制提示词并打开 ChatGPT<ExternalLink size={15} /></button><div className="bridge-secondary"><button className="text-button" onClick={() => copyPrompt()}><Clipboard size={14} />仅复制提示词</button><a className="text-button" href="https://chatgpt.com" target="_blank" rel="noreferrer">打开 ChatGPT<ExternalLink size={12} /></a><button className="text-button" onClick={() => setShowPrompt(!showPrompt)}>查看提示词<ChevronDown size={14} /></button></div>{showPrompt && <textarea className="prompt-preview" readOnly aria-label="完整提示词" value={job.prompt} />}<div className="bridge-note"><Leaf size={16} /><p>在 ChatGPT 新对话中粘贴提示词。完成后复制它输出的完整 JSON，回到右侧导入。当前任务已保存，关闭页面后仍可继续。</p></div></section><section className="card import-card"><div className="bridge-number orange">02</div><h2>带回你的答案与积累</h2><p>系统会先预览，再校验并存入对应的答案、素材库与语料库。</p><textarea className="json-editor" placeholder={'粘贴 ChatGPT 返回的完整 JSON…\n\n支持包含 ```json 代码块的结果。'} value={importText} onChange={event => { setImportText(event.target.value); setPreview(null); }} aria-label="粘贴 AI 返回 JSON" /><div className="import-bottom"><small>校验题目、长度、素材与表达关联</small><button className="button primary" disabled={!importText.trim()} onClick={parsePreview}>预览导入<ArrowRight size={15} /></button></div></section></div></>}
    {step === 'answer' && answer && <><div className="answer-layout"><section className="card answer-card"><div className="section-heading"><div><div className="eyebrow">YOUR OWN ANSWER</div><h2>你的英文答案</h2></div><Pill tone="green">{answer.wordCount || wordCount(answer.textEn)} words</Pill></div><div className="answer-tools"><span><span className="highlight-dot" />素材颜色 · 表达红色波浪线</span><button className="text-button" onClick={selectedAnswerWord}><Plus size={15} />选中文本加入单词本</button></div><div className="answer-text" onMouseUp={() => {}}><AnnotatedText text={answer.textEn} answer={answer} materials={answerMaterials} expressions={answerExpressions} scope={question.scope} questionId={question.id} onMaterial={onMaterial} onExpression={onExpression} /></div><div className="annotation-legend"><span><i className="legend-material" />点击色块，查看素材</span><span><i className="legend-expression" />点击红线，查看表达</span></div><div className="answer-footer"><button className="button secondary" onClick={() => setStep('write')}>修改素材，重新整理</button>{nextQuestion && <button className="button primary" onClick={() => openQuestion(nextQuestion)}>下一道题<ArrowRight size={16} /></button>}</div></section><aside className="answer-aside"><section className="card"><div className="section-heading"><div><h3>这次积累的表达</h3><p>{scopeShort[question.scope]}语料 · {answerExpressions.length} 条</p></div><Sparkles size={18} /></div>{answerExpressions.length ? answerExpressions.map(expression => <div className="answer-expression" key={expression.id}><div><strong className="expression-underline" onClick={() => onExpression(expression)}>{expression.textEn}</strong><button className="icon-button" title="加入单词本" aria-label={`收藏${expression.textEn}`} onClick={() => addWord({ textEn: expression.textEn, meaningZh: expression.meaningZh, exampleEn: expression.exampleEn, scope: question.scope, questionId: question.id })}><Plus size={15} /></button></div><p data-word-scope={question.scope} data-word-question={question.id}>{expression.exampleEn}</p><small data-word-scope={question.scope}>{expression.usageNoteEn || ''}</small></div>) : <p className="muted">本次没有提取表达。</p>}</section></aside></div>{question.scope !== 'writing-task1' && <section className="answer-material-section"><div className="section-heading"><div><h2>从这道题，拆出的素材元</h2><p>保留核心事件或论点，下一次回答时可以自由组合。</p></div><Pill>{answerMaterials.length} 个素材元</Pill></div><div className="collection-grid">{answerMaterials.map(material => <article className="card material-card" key={material.id}><div className="collection-card-top"><Layers3 size={18} /><Pill tone="green">独立素材元</Pill></div><h3>{material.summaryEn || 'Original material'}</h3><p data-word-scope={material.scope}>{material.detailEn || 'English version pending.'}</p><button className="text-button" onClick={() => onMaterial(material)}>English / 中文<ArrowRight size={14} /></button><div className="linked-pills">{state.links.filter(link => link.kind === 'material-expression' && link.fromId === material.id).sort((a, b) => b.score - a.score).slice(0, 3).map(link => { const expression = state.expressions.find(item => item.id === link.toId); return expression ? <span key={link.toId} title={link.reason}>{expression.textEn}</span> : null; })}</div></article>)}</div></section>}{outbound.length > 0 && <section className="outbound-section"><div className="section-heading"><div><h2>这个素材，还可以回答…</h2><p>相关题目 Top 3，点开后选择素材并继续修改。</p></div><ArrowRight size={20} /></div><div className="recent-grid">{outbound.map(item => { const related = state.questions.find(question => question.id === item.toId); return related && <button className="outbound-card" key={item.toId} onClick={() => openQuestion(related, [item.material])}><Pill>{related.part || scopeShort[related.scope]}</Pill><h3>{related.titleZh}</h3><p>{item.reason}</p><span>使用「{item.material.title}」<ArrowRight size={15} /></span></button>; })}</div></section>}</>}
    {preview && <Modal title="确认本次积累" close={() => setPreview(null)} wide><ImportPreview preview={preview} onMaterial={onMaterial} onExpression={onExpression} /><p className="import-preview-note">确认后执行完整校验。每道题保留一个当前答案；重新导入会替换答案，并保留已有素材与表达。</p><div className="modal-actions"><button className="button secondary" onClick={() => setPreview(null)}>返回修改</button><button className="button primary" disabled={!!busy} onClick={importResult}>{busy === 'import' ? <LoaderCircle className="spin" size={16} /> : <Check size={16} />}确认校验并保存</button></div></Modal>}
  </>;
}
function QualityPanel({ quality }: { quality: Quality }) { return <section className={`quality-panel ${quality.passed ? 'passed' : ''}`}><div><CheckCircle2 size={18} /><strong>{quality.passed ? '素材初检通过' : '让素材再具体一些'}</strong></div><p>{quality.note}</p><div className="quality-checks">{quality.checks.map(check => <span key={check.label} className={check.passed ? 'passed' : ''}>{check.passed ? <Check size={13} /> : <Circle size={12} />}{check.label}</span>)}</div>{quality.suggestions.length > 0 && <ul>{quality.suggestions.map(item => <li key={item}>{item}</li>)}</ul>}</section>; }
function QuestionVisual({ question }: { question: Question }) { const visual = question.visual; if (!visual) return null; return <div className="question-visual"><strong>{visual.title}</strong><QuestionChart visual={visual} />{visual.rows && <div className="table-scroll"><table><thead><tr>{visual.columns?.map((column, index) => <th key={`${column}-${index}`}>{column}</th>)}</tr></thead><tbody>{visual.rows.map((row, index) => <tr key={index}>{row.map((cell, column) => <td key={column}>{cell}</td>)}</tr>)}</tbody></table></div>}{visual.note && <small>{visual.note}</small>}</div>; }


function Words({ state, reload, notify, addWord }: { state: State; reload: () => Promise<State>; notify: (message: string, error?: boolean) => void; addWord: (input: WordInput) => void }) {
  const [scope, setScope] = useState('all');
  const [query, setQuery] = useState('');
  const [order, setOrder] = useState<string[]>([]);
  const [hidden, setHidden] = useState(false);
  const [deleteWord, setDeleteWord] = useState<Word | null>(null);
  const [busy, setBusy] = useState(false);
  let words = state.words.filter(word => (scope === 'all' || word.scope === scope) && `${word.textEn} ${word.meaningZh}`.toLowerCase().includes(query.toLowerCase()));
  if (order.length) words = words.sort((a, b) => { const ai = order.indexOf(a.id); const bi = order.indexOf(b.id); return (ai < 0 ? order.length : ai) - (bi < 0 ? order.length : bi); });
  const shuffle = () => { const ids = words.map(word => word.id); for (let index = ids.length - 1; index > 0; index--) { const selected = Math.floor(Math.random() * (index + 1)); [ids[index], ids[selected]] = [ids[selected], ids[index]]; } setOrder(ids); notify('已打乱顺序，换个角度温习。'); };
  const remove = async () => { if (!deleteWord) return; setBusy(true); try { await api(`/words/${deleteWord.id}`, { method: 'DELETE' }); await reload(); setDeleteWord(null); notify('已从单词本移除。'); } catch (error) { notify(errorMessage(error), true); } finally { setBusy(false); } };
  return <><div className="page-heading"><div><div className="eyebrow">WORDS THAT BECOME YOURS</div><h1>单词本<span className="heading-dot">.</span></h1><p>口语和作文的单词，一起收藏，分开温习。</p></div><button className="button primary" onClick={() => addWord({ textEn: '', meaningZh: '', exampleEn: '', scope: 'speaking' })}><Plus size={17} />添加单词或短语</button></div><div className="words-toolbar"><div className="segmented">{['all', 'speaking', 'writing-task2', 'writing-task1'].map(item => <button className={scope === item ? 'selected' : ''} key={item} onClick={() => setScope(item)}>{item === 'all' ? '全部单词' : scopeShort[item as Scope]}</button>)}</div><div className="words-actions"><button className="button secondary small-button" onClick={() => setHidden(!hidden)}>{hidden ? '显示中文' : '隐藏中文'}</button><button className="button secondary small-button" disabled={!words.length} onClick={shuffle}><Shuffle size={15} />随机乱序</button></div></div><div className="library-info"><span>共 {words.length} 个单词与短语</span><div className="search-box"><Search size={16} /><input value={query} onChange={event => setQuery(event.target.value)} placeholder="搜索英文或中文…" aria-label="搜索单词" /></div></div>{words.length ? <div className="word-grid">{words.map(word => <WordCard key={word.id} word={word} hidden={hidden} onRemove={() => setDeleteWord(word)} />)}</div> : <Empty icon={BookOpen} title={query || scope !== 'all' ? '这里还没有匹配的单词' : '属于你的单词本，还是一张白纸'} detail="在答案里选中一个英文单词或短语，点击收藏。也可以手动添加，从今天开始积累。" action={<button className="button primary" onClick={() => addWord({ textEn: '', meaningZh: '', exampleEn: '', scope: scope === 'all' ? 'speaking' : scope as Scope })}><Plus size={16} />收藏第一个单词</button>} />}{deleteWord && <Modal title="移除这个单词？" close={() => setDeleteWord(null)}><p className="modal-description">「{deleteWord.textEn}」将从单词本移除，原答案和语料仍保留。</p><div className="modal-actions"><button className="button secondary" onClick={() => setDeleteWord(null)}>保留</button><button className="button danger" disabled={busy} onClick={remove}>{busy ? <LoaderCircle size={16} className="spin" /> : <Trash2 size={16} />}移除</button></div></Modal>}</>;
}
function WordCard({ word, hidden, onRemove }: { word: Word; hidden: boolean; onRemove: () => void }) {
  const [revealed, setRevealed] = useState(false);
  const [speechStatus, setSpeechStatus] = useState('');
  useEffect(() => setRevealed(false), [hidden]);
  const speak = () => { if (!('speechSynthesis' in window)) { setSpeechStatus('浏览器不支持朗读'); return; } const utterance = new SpeechSynthesisUtterance(word.textEn); utterance.lang = 'en-GB'; utterance.onend = () => setSpeechStatus(''); utterance.onerror = () => setSpeechStatus('朗读不可用'); window.speechSynthesis.cancel(); window.speechSynthesis.speak(utterance); setSpeechStatus('正在朗读'); };
  return <article className="word-card card" data-word-scope={word.scope} data-word-question={word.questionId}><div className="collection-card-top"><Pill tone={word.scope === 'speaking' ? 'green' : 'orange'}>{scopeShort[word.scope]}</Pill><div><button className="icon-button" aria-label={`朗读${word.textEn}`} title={speechStatus || '朗读'} onClick={speak}><Volume2 size={17} /></button><button className="icon-button remove-word" title="移除" aria-label={`移除${word.textEn}`} onClick={onRemove}><Trash2 size={16} /></button></div></div><h3>{word.textEn}</h3>{hidden && !revealed ? <button className="reveal-meaning" onClick={() => setRevealed(true)}>点击回想中文意思</button> : <p>{word.meaningZh || '尚未填写中文含义'}</p>}{word.exampleEn && <blockquote>{word.exampleEn}</blockquote>}{speechStatus && <small className="muted">{speechStatus}</small>}</article>;
}
function WordModal({ input, close, saved, notify }: { input: WordInput; close: () => void; saved: () => Promise<void>; notify: (message: string, error?: boolean) => void }) { const [value, setValue] = useState(input); const [busy, setBusy] = useState(false); const save = async () => { setBusy(true); try { await api('/words', post(value)); await saved(); } catch (error) { notify(errorMessage(error), true); } finally { setBusy(false); } }; return <Modal title="收进单词本" close={close}><form onSubmit={event => { event.preventDefault(); save(); }}><label className="form-label">英文单词或短语<input required autoFocus value={value.textEn} onChange={event => setValue({ ...value, textEn: event.target.value })} placeholder="例如：a sense of belonging" /></label><label className="form-label">中文含义<input value={value.meaningZh} onChange={event => setValue({ ...value, meaningZh: event.target.value })} placeholder="用你自己的理解记录" /></label><label className="form-label">例句<textarea value={value.exampleEn} onChange={event => setValue({ ...value, exampleEn: event.target.value })} placeholder="可选，保留一个具体的使用场景" rows={3} /></label><label className="form-label">积累来源<select value={value.scope} onChange={event => setValue({ ...value, scope: event.target.value as Scope, questionId: event.target.value === input.scope ? input.questionId : undefined })}><option value="speaking">口语</option><option value="writing-task2">大作文 · Task 2</option><option value="writing-task1">小作文 · Task 1</option></select></label><div className="modal-actions"><button type="button" className="button secondary" onClick={close}>取消</button><button className="button primary" disabled={busy || !value.textEn.trim()}>{busy ? <LoaderCircle size={16} className="spin" /> : <Plus size={16} />}收藏</button></div></form></Modal>; }

function Settings({ state, setState, reload, notify, openBatch }: { state: State; setState: (state: State) => void; reload: () => Promise<State>; notify: (message: string, error?: boolean) => void; openBatch: () => void }) {
  const [band, setBand] = useState(state.settings.targetBand);
  const [speaking, setSpeaking] = useState(state.settings.dailySpeaking);
  const [writing, setWriting] = useState(state.settings.dailyWriting);
  const [busy, setBusy] = useState(false);
  const [backup, setBackup] = useState<{ object: Record<string, unknown>; filename: string } | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const save = async () => { setBusy(true); try { await api('/settings', { method: 'PATCH', body: JSON.stringify({ targetBand: band, dailySpeaking: speaking, dailyWriting: writing }) }); await reload(); notify('学习偏好已保存。'); } catch (error) { notify(errorMessage(error), true); } finally { setBusy(false); } };
  const exportBackup = async (previous = false) => { try { const response = await fetch(previous ? '/api/backup/previous' : '/api/backup'); if (!response.ok) { const error = await response.json(); throw new Error(error.error || '导出失败。'); } const blob = await response.blob(); const url = URL.createObjectURL(blob); const anchor = document.createElement('a'); anchor.href = url; anchor.download = `yasy-${previous ? 'before-restore' : 'backup'}-${new Intl.DateTimeFormat('sv-SE', { timeZone: 'Asia/Shanghai' }).format(new Date())}.json`; anchor.click(); URL.revokeObjectURL(url); notify('备份已导出，保存在浏览器下载目录。'); } catch (error) { notify(errorMessage(error), true); } };
  const readBackup = async (file?: File) => { if (!file) return; try { const object = JSON.parse(await file.text()); if (!object || typeof object !== 'object' || Array.isArray(object)) throw new Error('备份必须是 JSON 对象。'); setBackup({ object, filename: file.name }); } catch (error) { notify(`无法读取备份：${errorMessage(error)}`, true); } if (inputRef.current) inputRef.current.value = ''; };
  const restore = async () => { if (!backup) return; setBusy(true); try { const result = await api<{ state: State }>('/backup', post({ backup: backup.object })); setState(result.state); setBand(result.state.settings.targetBand); setSpeaking(result.state.settings.dailySpeaking); setWriting(result.state.settings.dailyWriting); setBackup(null); notify('备份已恢复，工作台数据已更新。'); } catch (error) { notify(errorMessage(error), true); } finally { setBusy(false); } };
  return <><div className="page-heading"><div><div className="eyebrow">A WORKBENCH THAT FITS YOU</div><h1>偏好与数据<span className="heading-dot">.</span></h1><p>按照自己的节奏积累，让所有内容始终由你掌握。</p></div></div><div className="settings-grid"><section className="card settings-card"><div className="section-heading"><div><h2>学习目标</h2><p>用于专属提示词与每日规划</p></div><Sprout size={22} /></div><label className="form-label">IELTS 目标分数<select value={band} onChange={event => setBand(event.target.value)}>{['5.5', '6.0', '6.5', '7.0', '7.5', '8.0', '8.5', '9.0'].map(item => <option key={item} value={item}>{item} Band</option>)}</select></label><div className="form-columns"><label className="form-label">每日口语目标<input type="number" min="0" max="20" value={speaking} onChange={event => setSpeaking(Number(event.target.value))} /></label><label className="form-label">每日作文目标<input type="number" min="0" max="10" value={writing} onChange={event => setWriting(Number(event.target.value))} /></label></div><label className="form-label">考试类型<select value="academic" disabled><option value="academic">Academic 学术类</option></select><small>General Training 小作文题库与专属处理器预留。</small></label><button className="button primary" disabled={busy} onClick={save}>{busy ? <LoaderCircle size={16} className="spin" /> : <Check size={16} />}保存学习偏好</button></section><section className="card settings-card"><div className="section-heading"><div><h2>AI 处理方式</h2><p>口语 / Task 1 / Task 2 使用各自提示词</p></div><Sparkles size={22} /></div><div className="provider-selected"><span className="provider-icon"><MessageCircle size={23} /></span><div><strong>ChatGPT 网页桥接</strong><p>本机生成提示词，浏览器中处理，校验后入库。</p></div><CheckCircle2 size={19} /></div><p className="settings-explanation">当前采用复制提示词与导入 JSON 的流程。系统已预留 Provider 接口，可扩展 API 或本机浏览器自动化。</p><div className="reserved-provider"><span>API Provider</span><Pill>接口预留</Pill></div><div className="reserved-provider"><span>浏览器自动化</span><Pill>接口预留</Pill></div></section><section className="card settings-card data-card"><div className="section-heading"><div><h2>你的积累，安全留在本机</h2><p>导出备份，也可以在另一台设备恢复</p></div><FolderOpen size={22} /></div><div className="data-summary"><span><strong>{state.answers.length}</strong>答案</span><span><strong>{state.materials.length}</strong>素材元</span><span><strong>{state.expressions.length}</strong>表达</span><span><strong>{state.words.length}</strong>单词</span></div><div className="storage-path"><small>存储位置</small><code>{state.storage.location}</code></div><div className="settings-buttons"><button className="button primary" onClick={() => exportBackup()}><ArrowDownToLine size={16} />导出完整备份</button><button className="button secondary" onClick={() => inputRef.current?.click()}><Upload size={16} />导入备份</button><button className="button secondary" onClick={openBatch}><FileText size={16} />PDF / Word 导入题库</button><button className="text-button" onClick={() => exportBackup(true)}><ArrowDownToLine size={14} />下载恢复前快照</button><input ref={inputRef} hidden type="file" accept=".json,application/json" onChange={event => readBackup(event.target.files?.[0])} /></div><p className="settings-explanation">备份包括中文草稿、当前答案、素材、语料、关联、单词、AI 任务与学习偏好。</p></section><section className="device-card"><div className="device-illustration"><div className="device-laptop"><div><span /> <span /> <span /></div></div><div className="device-phone"><span /></div></div><h3>在 Mac 积累，随时温习。</h3><p>Mac 是主要的素材书写与 AI 处理工作台。当前页面已适配 iPhone 阅读；跨设备连接与同步预留。</p><Pill tone="green">MAC FIRST · MOBILE READY</Pill></section></div>{backup && <Modal title="恢复这份备份？" close={() => setBackup(null)}><p className="modal-description">文件：{backup.filename}</p><p className="restore-warning">恢复会替换当前工作台的学习数据。建议先导出当前备份，校验通过后才会写入。</p><details className="preview-details"><summary>预览备份内容</summary><pre>{JSON.stringify(backup.object, null, 2).slice(0, 12000)}</pre></details><div className="modal-actions"><button className="button secondary" onClick={() => exportBackup()}><ArrowDownToLine size={16} />先备份当前数据</button><button className="button primary" disabled={busy} onClick={restore}>{busy ? <LoaderCircle className="spin" size={16} /> : <Upload size={16} />}确认恢复</button></div></Modal>}</>;
}
